bundle_generation.command:
node --input-type=module <<'NODE'
import * as esbuild from 'esbuild';
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
const hash=x=>createHash('sha256').update(x).digest('hex');
const version=fs.readFileSync('src/sdk/version.ts','utf8').match(/'([^']+)'/)[1];
const banner=`/* edge-personalization SDK v${version} — one package: core (identity, transport), emit (four capture paths), listen (decisions). */`;
const artifacts=[];
let patch='*** Begin Patch\n';
for(const [entry,out,format] of [['src/sdk/index.ts','public/sdk/edge-personalization.esm.js','esm'],['src/sdk/browser.ts','public/sdk/edge-personalization.js','iife']]){
 const result=await esbuild.build({entryPoints:[path.resolve(entry)],outfile:path.resolve(out),bundle:true,platform:'browser',target:'es2022',minify:false,sourcemap:false,legalComments:'none',logLevel:'silent',metafile:true,banner:{js:banner},format,write:false});
 const before=fs.readFileSync(out,'utf8'),after=result.outputFiles[0].text;
 patch+='*** Update File: '+out+'\n@@\n'+before.trimEnd().split('\n').map(l=>'-'+l).join('\n')+'\n'+after.trimEnd().split('\n').map(l=>'+'+l).join('\n')+'\n';
 artifacts.push({path:out,generated_sha256:hash(after),bytes:Buffer.byteLength(after),input_paths:Object.keys(result.metafile.inputs),write:false});
}
patch+='*** End Patch';
console.log(JSON.stringify({artifacts,patch}));
NODE
